import net.sf.jsqlparser.parser.CCJSqlParserManager;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.PlainSelect;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.util.deparser.ExpressionDeParser;
import net.sf.jsqlparser.util.deparser.SelectDeParser;
import net.sf.jsqlparser.util.deparser.StatementDeParser;
import com.github.pagehelper.PageException;

import java.io.StringReader;

public class SqlConverter {

    private final CCJSqlParserManager jSqlParser = new CCJSqlParserManager();

    public String convertToPageSql(String sql, Integer offset, Integer limit) {
        // Parse the SQL
        Statement stmt;
        try {
            stmt = jSqlParser.parse(new StringReader(sql));
        } catch (Exception e) {
            throw new PageException("不支持该SQL转换为分页查询!", e);
        }

        // Ensure it is a Select statement
        if (!(stmt instanceof Select)) {
            throw new PageException("分页语句必须是Select查询!");
        }

        // The logic for generating the paginated SQL
        if (limit == null) {
            throw new PageException("Limit for pagination must not be null!");
        }
        if (offset == null) {
            offset = 0;
        }

        Select select = (Select) stmt;
        PlainSelect plainSelect = (PlainSelect) select.getSelectBody();

        // Ensure the statement has an ORDER BY clause for ROW_NUMBER
        if (plainSelect.getOrderByElements() == null || plainSelect.getOrderByElements().isEmpty()) {
            throw new PageException("分页查询必须包含Order By语句!");
        }

        // Generate the pagination SQL for SQL Server
        StringBuilder pageSql = new StringBuilder("SELECT ");

        // Apply TOP clause if limit is set
        pageSql.append("TOP ").append(limit).append(" ");

        // Construct the inner query with ROW_NUMBER
        pageSql.append(" * FROM (SELECT ROW_NUMBER() OVER (").append(extractOrderByClause(plainSelect))
                .append(") AS PAGE_ROW_NUMBER, ")
                .append(getSelectItems(plainSelect))
                .append(" FROM (").append(sql).append(") AS PAGE_TABLE_ALIAS) AS PAGE_TABLE_ALIAS ")
                .append("WHERE PAGE_ROW_NUMBER > ").append(offset)
                .append(" AND PAGE_ROW_NUMBER <= ").append(offset + limit);

        return pageSql.toString();
    }

    private String extractOrderByClause(PlainSelect plainSelect) {
        StatementDeParser statementDeParser = new StatementDeParser(new StringBuilder());
        SelectDeParser selectDeParser = new SelectDeParser(new ExpressionDeParser(), statementDeParser, new StringBuilder());
        plainSelect.getOrderByElements().forEach(selectDeParser::visit);

        return statementDeParser.getBuffer().toString();
    }

    private String getSelectItems(PlainSelect plainSelect) {
        StringBuilder selectItems = new StringBuilder();
        plainSelect.getSelectItems().forEach(item -> selectItems.append(item.toString()).append(", "));
        // Remove the last comma and space
        if (selectItems.length() > 0) {
            selectItems.setLength(selectItems.length() - 2);
        }
        return selectItems.toString();
    }
}
